CREATE OR REPLACE FUNCTION public.create_manual_order(_restaurant_id uuid,_customer_id uuid,_name text,_phone text,_details jsonb,_items jsonb,_delivery_fee numeric,_address text,_payment_method text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oid uuid; sub numeric; BEGIN IF NOT EXISTS(SELECT 1 FROM public.restaurants WHERE id=_restaurant_id AND user_id=auth.uid()) AND NOT coalesce(public.is_super_admin(auth.uid()),false) THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF; IF public.normalize_customer_phone(_phone) IS NULL OR length(trim(coalesce(_name,''))) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Nome e telefone válidos são obrigatórios'; END IF; IF _payment_method NOT IN ('cash','credit_card','debit_card','pix','food_voucher','meal_voucher') THEN RAISE EXCEPTION 'Forma de pagamento inválida'; END IF; IF coalesce(_delivery_fee,0)<0 OR coalesce(_delivery_fee,0)>1000 THEN RAISE EXCEPTION 'Taxa inválida'; END IF; SELECT coalesce(sum((i->>'total')::numeric),0) INTO sub FROM jsonb_array_elements(_items) i; INSERT INTO public.orders(restaurant_id,customer_id,customer_name,customer_phone,customer_address_details,items,subtotal,delivery_fee,total,address,payment_method,status,payment_status) VALUES(_restaurant_id,_customer_id,trim(_name),_phone,_details,_items,sub,coalesce(_delivery_fee,0),sub+coalesce(_delivery_fee,0),nullif(left(coalesce(_address,''),500),''),_payment_method,'new','not_required') RETURNING id INTO oid; RETURN oid; END $$;
REVOKE ALL ON FUNCTION public.create_manual_order(uuid,uuid,text,text,jsonb,jsonb,numeric,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_manual_order(uuid,uuid,text,text,jsonb,jsonb,numeric,text,text) TO authenticated,service_role;